48: function resolvePlay(){if(state.gameOver||state.possession!=='home')return;let p=plays[state.selected],isFourth=state.down===4;$('#resultBanner').className='result-banner';$('#resultBanner').textContent='';let dieOne=Math.ceil(Math.random()*6),dieTwo=Math.ceil(Math.random()*6),dice=dieOne+dieTwo;$('#dieOne').textContent=dieOne;$('#dieTwo').textContent=dieTwo;$('#diceHint').textContent=`Total ${dice} · ${dice>=10?'bonus yards!':'keep it moving'}`;state.playClock=25;advanceClock(Math.floor(Math.random()*13)+18);if(state.gameOver)return;
