55: function aiDrive(){if(state.gameOver||state.possession!=='away')return;let playsCount=0;while(state.possession==='away'&&!state.gameOver&&playsCount++<7){advanceClock(25+Math.floor(Math.random()*18));if(state.gameOver)break;let r=Math.random();if(r<.055){addFeed(`${teamNickname('away')} fumbles! You recover the ball.`,'turnover');state.possession='home';state.playClock=25;state.ball=Math.max(15,100-state.ball);state.down=1;state.toGo=10;state.drives++;break}let yards=r<.26?-Math.floor(Math.random()*4):Math.floor(Math.random()*13)+2;state.ball+=yards;if(state.ball>=100){score('away',7,`${teamNickname('away')} punches it in for a touchdown.`);return}if(state.ball<=0){state.home+=2;addFeed('Safety! Your defense gets two points.','score');finishDrive('home');return}if(state.ball>=70&&state.ball<100&&Math.random()<.24){score('away',3,`${teamNickname('away')} kicks a field goal.`);return}if(yards>=state.toGo){state.down=1;state.toGo=10}else{state.down++;state.toGo=Math.max(1,state.toGo-yards)}if(state.down>4){addFeed(`${teamNickname('away')} turns it over on downs.`);state.possession='home';state.playClock=25;state.ball=100-state.ball;state.down=1;state.toGo=10;state.drives++;break}if(state.clock<60&&state.quarter===4)break}
